function Icon({name,size=20,...props}:{name:IconName;size?:number;className?:string}){
 const paths:Record<IconName,ReactNode>={
  map:<><path d="m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2Z"/><path d="M9 3v16M15 5v16"/></>,
  layers:<><path d="m12 3 10 6-10 6L2 9Z"/><path d="m3 13 9 5 9-5M3 17l9 5 9-5"/></>,
  cube:<><path d="m12 2 9 5v10l-9 5-9-5V7Z"/><path d="m3 7 9 5 9-5M12 12v10M7.5 4.5l9 5"/></>,
  book:<><path d="M4 4h6a4 4 0 0 1 2 1 4 4 0 0 1 2-1h6v15h-6a4 4 0 0 0-2 1 4 4 0 0 0-2-1H4Z"/><path d="M12 5v15M7 8h2M15 8h2"/></>,
  search:<><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></>,
  arrow:<path d="M4 12h16m-6-6 6 6-6 6"/>,download:<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>,
  close:<path d="m6 6 12 12M6 18 18 6"/>,plus:<path d="M5 12h14M12 5v14"/>,
  pin:<><path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2.5"/></>,
  locate:<><circle cx="12" cy="12" r="7"/><circle cx="12" cy="12" r="2"/><path d="M12 2v3m0 14v3M2 12h3m14 0h3"/></>,
  check:<path d="m5 12 4 4L19 6"/>,external:<><path d="M14 3h7v7m0-7L10 14"/><path d="M10 3H3v18h18v-7"/></>,
  star:<path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9Z"/>,
  upload:<path d="M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5"/>,
  info:<><circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/></>,
  offline:<><path d="m3 3 18 18M7 6a15 15 0 0 1 14 2M3 8l1-.6M6 12a10 10 0 0 1 3-1.6M13 10a10 10 0 0 1 5 2m-9 4a5 5 0 0 1 6 0M12 20h.01"/></>,
  chevron:<path d="m9 5 7 7-7 7"/>,folder:<path d="M3 5h6l2 2h10v13H3Z"/>,
  compass:<><circle cx="12" cy="12" r="9"/><path d="m16 8-2 6-6 2 2-6Z"/></>,
 };
 return <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.65" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" {...props}>{paths[name]}</svg>;
}
type Source={id:string;title:string;url:string;kind?:string;rights?:string;offline?:unknown;notes?:unknown};
