type Visibility={surface:boolean;sheets:boolean;rooms:boolean;access:boolean;galleries:boolean;personal:boolean};
const initialLayers:Visibility={surface:true,sheets:false,rooms:true,access:true,galleries:true,personal:true};
const recordId=(feature:GeoJSON.Feature)=>String(feature.properties?.sheetId??feature.properties?.id??feature.id??'');
type InstallPrompt=Event&{prompt:()=>Promise<void>;userChoice:Promise<{outcome:string}>};
const FAVORITES_KEY=`paris-atlas-favorites-${STORAGE_SCOPE}`;
const empty:GeoJSON.FeatureCollection={type:'FeatureCollection',features:[]};
const bytes=(n:number)=>n<1048576?`${Math.max(1,Math.round(n/1024))} KB`:`${(n/1048576).toFixed(1)} MB`;
const date=(s:string)=>new Date(s).toLocaleDateString('tr-TR',{day:'numeric',month:'short',year:'numeric'});
function centerOf(feature:GeoJSON.Feature|undefined):[number,number]|null {
 if(!feature?.geometry||feature.geometry.type==='GeometryCollection')return null;
 const points:GeoJSON.Position[]=[];
 function visit(v:unknown){if(!Array.isArray(v))return;if(typeof v[0]==='number'&&typeof v[1]==='number')points.push(v as number[]);else v.forEach(visit);}
 visit(feature.geometry.coordinates);if(!points.length)return null;
 const xs=points.map(p=>p[0]!),ys=points.map(p=>p[1]!);return [(Math.min(...xs)+Math.max(...xs))/2,(Math.min(...ys)+Math.max(...ys))/2];
}
function ExternalLink({url,children,className=''}:{url:unknown;children:ReactNode;className?:string}){const safe=safeExternalUrl(url);return safe?<a className={className} href={safe} target="_blank" rel="noreferrer">{children}<Icon name="external" size={15}/></a>:null;}

