 const [sheets,setSheets]=useState<GeoJSON.FeatureCollection>(empty),[exploration,setExploration]=useState<GeoJSON.FeatureCollection>(empty),[surfaceCount,setSurfaceCount]=useState(0);
 const [basemap,setBasemap]=useState<'light'|'dark'|'satellite'>('light'),[layersOpen,setLayersOpen]=useState(false),[galleryOpacity,setGalleryOpacity]=useState(.8),[directoryKind,setDirectoryKind]=useState<'rooms'|'sheets'|'access'>('rooms');
 const [collections,setCollections]=useState<CollectionRecord[]>([]),[rasterAssets,setRasterAssets]=useState<LocalAsset[]>([]),[spatialOpen,setSpatialOpen]=useState(false),[missingRoom,setMissingRoom]=useState<Room|null>(null),[mapWide,setMapWide]=useState(false),[collectionProgress,setCollectionProgress]=useState<{done:number;total:number}|null>(null),[collectionMessage,setCollectionMessage]=useState('');
 const [query,setQuery]=useState(''),[network,setNetwork]=useState<'all'|'GRS'>('GRS'),[onlyFavorites,setOnlyFavorites]=useState(false),[resultLimit,setResultLimit]=useState(60);
 const [detail,setDetail]=useState<Record<string,unknown>|null>(null),[status,setStatus]=useState('Paris atlası açılıyor…'),[ready,setReady]=useState(false),[busy,setBusy]=useState(false);
 const [tab,setTab]=useState<'explore'|'library'|'notebook'>('explore'),[drawer,setDrawer]=useState<'offline'|'sources'|'archive'|null>(null),[mobileExpanded,setMobileExpanded]=useState(false);
 const [layers,setLayers]=useState<Visibility>(initialLayers),[notes,setNotes]=useState<Note[]>([]),[assets,setAssets]=useState<LocalAsset[]>([]),[packs,setPacks]=useState<InstalledPack[]>([]);
 const [historicalOpen,setHistoricalOpen]=useState(false),[planAsset,setPlanAsset]=useState<LocalAsset|null>(null),[roomLimit,setRoomLimit]=useState(8);
