 const [installPrompt,setInstallPrompt]=useState<InstallPrompt|null>(null),[modelAsset,setModelAsset]=useState<LocalAsset|null>(null),[modelLoading,setModelLoading]=useState(false),[modelError,setModelError]=useState(''),[roomPosters,setRoomPosters]=useState<Record<string,string>>({}),[archiveInfo,setArchiveInfo]=useState<{name:string;metadata:unknown}|null>(null);
 const [favorites,setFavorites]=useState<string[]>(()=>{try{const saved=JSON.parse(localStorage.getItem(FAVORITES_KEY)??'[]');return Array.isArray(saved)?saved.filter((id):id is string=>typeof id==='string'):[];}catch{return [];}});
 const detailKind=detail?.kind==='room'?'room':detail?.kind==='access'?'access':'sheet';
