 const results=useMemo(()=>directoryKind==='sheets'?sheetResults:searchFeatures(exploration,query).filter(f=>f.properties?.kind===(directoryKind==='rooms'?'room':'access')&&(!onlyFavorites||favorites.includes(recordId(f)))),[directoryKind,sheetResults,exploration,query,onlyFavorites,favorites]);
 const grsCount=useMemo(()=>sheets.features.filter(f=>f.properties?.network==='GRS').length,[sheets]);
 const roomCount=exploration.features.filter(f=>f.properties?.kind==='room').length,accessCount=exploration.features.filter(f=>f.properties?.kind==='access').length;
 const roomAvailable=(id:string)=>assets.some(asset=>asset.kind==='glb'&&(asset.roomId===id||asset.roomIds?.includes(id)));
