 async function refresh(){const d=await db();const [n,a,p,c,r]=await Promise.all([d.getAll('notes'),d.getAll('assets'),d.getAll('packs'),listCollections(),getRasterAssets()]);setNotes(n.sort((x,y)=>y.updatedAt.localeCompare(x.updatedAt)));setAssets(a);setPacks(p);setCollections(c);setRasterAssets(r);}
 async function run(action:()=>Promise<unknown>){if(busyRef.current)return;busyRef.current=true;setBusy(true);try{await action();await refresh();}catch(e){setStatus(e instanceof Error?e.message:String(e));}finally{busyRef.current=false;setBusy(false);}}
 useEffect(()=>{
  const controller=new AbortController();let live=true,m:AtlasMap|null=null;
  async function load(){try{m=new AtlasMap(mapNode.current!,p=>{setDetail(p);setTab('explore');setMobileExpanded(false);setLayersOpen(false);});engine.current=m;
   const [igc,surface,places]=await Promise.all(['igc-index.geojson','surface-grs.geojson','exploration.geojson'].map(async file=>{const r=await fetch(`./data/${file}`,{signal:controller.signal});if(!r.ok)throw Error('Harita verileri açılamadı. Bağlantınızı kontrol edip yeniden açın.');return r.json() as Promise<GeoJSON.FeatureCollection>;}));
   if(!live)return;await m.loadBuiltins(igc!,surface!);await m.loadExploration(places!);if(!live)return;setSheets(igc!);setExploration(places!);setSurfaceCount(surface!.features.length);setReady(true);setStatus('Atlas hazır. Salonları, yüzeyi ve arşiv katmanlarını aynı haritada keşfet.');
  }catch(e){if(live)setStatus(e instanceof Error?e.message:String(e));}}
  void load();void refresh().catch(()=>{if(live)setStatus('Cihaz depolaması açılamadı. Tarayıcı depolama ayarlarını kontrol edin.');});
  void fetch('./data/sources.json',{signal:controller.signal}).then(r=>r.ok?r.json():null).then(v=>{if(live&&v){setSources(v.sources??[]);setSourceDate(v.checkedAt??'');}}).catch(()=>{});
  void fetch('./data/rooms.json',{signal:controller.signal}).then(r=>r.ok?r.json():null).then(v=>{if(live&&v)setRooms(v.rooms??[]);}).catch(()=>{});
  const connect=()=>setOnline(navigator.onLine),install=(event:Event)=>{event.preventDefault();setInstallPrompt(event as InstallPrompt);};window.addEventListener('online',connect);window.addEventListener('offline',connect);window.addEventListener('beforeinstallprompt',install);
  return()=>{live=false;controller.abort();m?.destroy();engine.current=null;window.removeEventListener('online',connect);window.removeEventListener('offline',connect);window.removeEventListener('beforeinstallprompt',install);};
 },[]);
 useEffect(()=>{if(ready)engine.current?.filterSheets(sheetResults);},[sheetResults,ready]);
 useEffect(()=>{setResultLimit(60);},[results]);
 useEffect(()=>{if(ready)engine.current?.setVisibility(layers);},[layers,ready]);
 useEffect(()=>{if(ready)void engine.current?.setBasemap(basemap).catch((error:unknown)=>setStatus(error instanceof Error?error.message:String(error)));},[basemap,ready]);
 useEffect(()=>{if(ready)engine.current?.setGalleryOpacity(galleryOpacity);},[galleryOpacity,ready]);
