 function handleImport(e:ChangeEvent<HTMLInputElement>){const file=e.target.files?.[0];e.target.value='';if(file)void run(async()=>{const a=await importFile(file);setStatus(`${file.name} bu cihaza eklendi.`);if(a.kind==='glb')setModelAsset(a);if(a.kind==='image')setPlanAsset(a);setTab('library');setMobileExpanded(true);});}
