  <input ref={collectionInput} className="visually-hidden" aria-label="Arşiv paketi içe aktar" disabled={busy} type="file" accept=".zip,application/zip" onChange={e=>{const file=e.target.files?.[0];e.target.value='';if(file)void run(async()=>{setStatus('Arşiv hazırlanıyor…');setCollectionMessage('');setCollectionProgress({done:0,total:0});const collection=await importCollection(file,(done:number,total:number)=>{setCollectionProgress({done,total});setStatus(`Arşiv ekleniyor · ${bytes(done)} / ${bytes(total)}`);});setStatus(`“${collection.title}” bu cihaza eklendi. ${collection.assetCount} dosya çevrimdışı kullanıma hazır.`);setLayers(value=>({...value,galleries:true}));if(missingRoom){const model=await getRoomAsset(missingRoom.id);if(model){setModelAsset({...model,roomId:missingRoom.id});setDrawer(null);setMissingRoom(null);}}});}}/>

